import { JOB_LIST_CONTAINER, JobStateGroup } from './common.js';
import { job_refresh } from './jobs/state.js';
import { addJobItem } from './jobs/job.js';

let databaseCursor = null;
let databaseLoading = false;
let databaseHasMore = true;

let databaseInfiniteScrollEnabled = false;

export function setDatbaseInfitiniseScrollState(state){
    databaseInfiniteScrollEnabled = state;
}

function _addJobs(data) {
	if (!data.results)
		return;

	const size = Object.keys(data.results).length;

	if (size <= 0)
		return;

	$.each(data.results, function (_index, job) {
		job.job_id = `0_${job.job_id}`;	// force local server

        if (!JobStateGroup.FINISHED.has(job.status))
		    job_refresh?.activeJobs?.push(job);

		$(JOB_LIST_CONTAINER).append(
			addJobItem(job, data.authenticated)
		);
	});
}

export function switchSearch(data) {
    $(JOB_LIST_CONTAINER).html('');

    _addJobs(data);
}

/**
 * Function to get jobs (success/fail buttons) from the arm api
 * @param getJobsHREF link to the json api
 */
export function fetchJobs(href) {
    $.get(href, function (data) {
        if (data.success === true) {
            $(JOB_LIST_CONTAINER).html('');

            _addJobs(data);
        }
    }, 'json');
}

export async function fetchAllJobs(reset = false) {
    if (databaseLoading) return;

    if (reset) {
        databaseCursor = null;
        databaseHasMore = true;
        $(JOB_LIST_CONTAINER).empty();
    }

    if (!databaseHasMore) return;

    databaseLoading = true;
    setDatbaseInfitiniseScrollState(true);
    $('#database_load_status').text('Loading jobs...');

    const params = {};

    if (databaseCursor !== null) {
        params.before = databaseCursor;
    }

    try {
        const data = await $.getJSON('/database/jobs', params);

        if (!data.success) {
            databaseHasMore = false;
            $('#database_load_status').text(data.error || 'Failed to load jobs.');
            return;
        }

        _addJobs(data);

        databaseCursor = data.next_cursor;
        databaseHasMore = data.has_more;

        if (!Object.keys(data.results ?? {}).length) {
            $('#database_load_status').text('No jobs found.');
        } else if (!databaseHasMore) {
            $('#database_load_status').text('All jobs loaded.');
        } else {
            $('#database_load_status').text('');
        }
    } catch (error) {
        databaseHasMore = false;
        $('#database_load_status').text('Failed to load jobs.');
        console.error(error);
    } finally {
        databaseLoading = false;

        if (databaseInfiniteScrollEnabled && databaseHasMore) {
            checkDatabaseScroll();
        }
    }
}

export function checkDatabaseScroll() {
	const container = $('.base-content')[0];

	if (!container || !databaseInfiniteScrollEnabled || databaseLoading || !databaseHasMore)
		return;

    const maxDistanceFromBottom = 400;
	const distanceFromBottom =
        container.scrollHeight - container.scrollTop - container.clientHeight;

	if (distanceFromBottom <= maxDistanceFromBottom) {
		fetchAllJobs();
	}
}

import { JobState } from './common.js';

const FEEDER_GROUPS = {
    ripping: [
        JobState.MANUAL_WAIT_STARTED,
        JobState.IDLE,
        JobState.VIDEO_RIPPING,
        JobState.VIDEO_WAITING,
        JobState.VIDEO_INFO,
        JobState.AUDIO_RIPPING
    ],
    transcoding: [
        JobState.TRANSCODE_ACTIVE,
        JobState.TRANSCODE_WAITING
    ],
    global: [
        JobState.SUCCESS,
        JobState.FAILURE,
        JobState.POSTPROCESSING_MOVING,
        'clear',
    ],
    //simulate: [
    //    'simulate',
    //]
};

function renderFeederGroup(group, states) {
    const container = $(`#feeder-${group}`);

    /*if (group === 'simulate')
    {
        $.each(job_refresh.activeJobs, function (index, job) {
            if (!job?.active)
                return 1;

            const ids = getJobIds(job);

            container.append(
                $("<button>", {
                    type: 'button',
                    text: `${job.title} (${job.year})`,
                    'data-feeder-action': group,
                    'data-job-id': ids.jobId,
                    'data-drive': job.devpath,
                })
            );
        });

        return;
    }*/

    const uniqueStates = [...new Set(states)];
    uniqueStates.forEach(state => {
        container.append(
            $('<button>', {
                type: 'button',
                text: state,
                'data-feeder-action': state
            })
        );
    });
}

function getFeederDriveMode()
{
    return localStorage.getItem('feeder-drive-mode') || 'auto';
}

function setFeederDriveMode(drive_mode)
{
    localStorage.setItem('feeder-drive-mode', drive_mode);
}

function setFeederDriveModeCheckbox()
{
    const drive_mode = (getFeederDriveMode() === 'manual') ? true : false;
    $('#feeder_drive_mode').prop('checked', drive_mode);
}

$(document).on('change', '#feeder_drive_mode', function(){
    setFeederDriveMode(this.checked ? 'manual' : 'auto');
});

$(document).on('click', '[data-feeder-action]', function() {

    const data = {
        action      : $(this).attr('data-feeder-action'),
        job_id      : $(this).attr('data-job-id') ?? -1,
        drive       : $(this).attr('data-drive') ?? -1,
        drive_mode  : getFeederDriveMode(),
    };

    $.ajax({
        url			: '/feeder',
        method		: 'GET',
        data		: data,
        dataType	: 'json'
    })
    .done(function(result) {
        console.log('Feeder:', result);
    })
    .fail(function(xhr) {
        console.error('Feeder failed:', xhr.responseJSON || xhr.statusText);
    });
});

$(document).ready(function () {
    setFeederDriveModeCheckbox();

    setTimeout(function(){
        Object.entries(FEEDER_GROUPS).forEach(([group, states]) => {
            renderFeederGroup(group, states);
        });
    }, 1000);
});

import { TrackState, JobState, JobStateGroup, JOB_PIPELINE_STAGES, safe_bool } from '../common.js';
import { formatTimestamp, formatTimeToMilisecconds, formatCountdown, formatTrackLength } from '../time.js';
import { job_refresh } from './state.js';

export function getJobIds(job) {
	const id                = String(job.job_id);
	const [serverId, jobId] = id.split('_');

	return {
		serverId    : jobId === undefined ? '0' : serverId,
		jobId       : jobId ?? id,
		local       : jobId === undefined || serverId === '0'
	};
}

export function getManualWaitTimeRemaining(job) {
    const milliseconds = formatTimeToMilisecconds(job.stop_time);

    if (Number.isNaN(milliseconds)) return { relative: '', title: '' };

    return formatCountdown(milliseconds + 30 * 60 * 1000);
}

export function getActiveJob(job_id) {
    return job_refresh.activeJobs.find(
        job => String(job.job_id) === String(job_id)
    ) ?? null;
}

export function getJobTitle(job) {
    return `${job.title_manual !== 'None' ? job.title_manual : job.title} (${job.year})`;
}

export function getRipperName(job, ids) {
    return job.ripper || (ids.local ? 'Local' : '');
}

export function posterCheck(job) {
    if (typeof job.poster_url === 'undefined')
        return '';

    const image = job.poster_url !== 'None' && job.poster_url !== 'N/A'
        ? job.poster_url
        : `/static/img/${job.video_type === 'Music' ? 'music.png' : 'none.png'}`;
    return `<img class="job-poster" src="${image}" alt="${getJobTitle(job)}">`;
}

export function jobHasProgress(job) {
    let status = false;
    // HandBrake has the disc/files and should be outputting stage and eta
    if (job.status === 'transcoding') {
        status = true;
    }
    // MakeMKV has the disc and should be outputting stage and eta
    if (job.status === 'ripping' && job.stage) {
        status = true;
    }
    // abcde is ripping the audio disc and is outputting stage and eta
    if (job.disctype === 'music' && job.stage) {
        status = true;
    }

    return status;
}

export function getStatusClass(job) {
    let status = `status-${job.status.toLowerCase().replace(/[^a-z0-9_-]/g, '')}`

    // waiting for user input
    if (safe_bool(job.manual_edit) && !safe_bool(job.manual_start))
        status += ' status-manual-edit-pending';

    if (safe_bool(job.manual_start) && job.status.toLowerCase() === JobState.VIDEO_WAITING)
        status += ' status-manual-starting';

    return status;
}

export function renderJobStatusBadge(job) {
    const statusClass = getStatusClass(job);

    let manual_info = '';

    if (safe_bool(job.manual_edit) && !safe_bool(job.manual_start))
        manual_info = getManualWaitTimeRemaining(job).relative;

    if (safe_bool(job.manual_start) && job.status.toLowerCase() === JobState.VIDEO_WAITING)
        manual_info = 'Starting soon';

    return `
        <span class="job-status ${statusClass}" 
                data-manual-info='${manual_info}'
                data-modal='jobs_pipeline' 
                data-jobid="${job.job_id}">
            <span class="status-dot"></span>
            <span class="status-text">${job.status}</span>
        </span>
    `;
}

export function renderTracks(job, root) {
    const modal = $(root);
    const tracks = job.tracks || [];
    const container = modal.find('#tracks .tracks-list').empty();
    const actions = modal.find('#tracks .tracks-actions').empty();

    const manual_time_remaining = getManualWaitTimeRemaining(job);
    const manual_edit = job.manual_edit && !manual_time_remaining.expired && (__is_authenticated_simple());

    if (!tracks.length) {
        container.append($('<p>').addClass('tracks-empty').text('No tracks found.'));
        return;
    }

    let num_tracks_to_process = 0;

    $.each(tracks, function (_, track) {
        const title = track.filename || `Track ${track.track_number}`;
        const row = $('<div>').addClass('track-row');
        const info = $('<div>').addClass('track-info');
        const heading = $('<div>').addClass('track-heading');
        const tags = $('<div>').addClass('track-tags');

        heading.append($('<span>').addClass('track-number').text(String(track.track_number).padStart(2, '0')));
        heading.append($('<strong>').addClass('track-title').text(title));

        const addTag = (label, value, className = '') => {
            if (value === null || value === '') return;
            tags.append($('<span>').addClass(`track-tag ${className}`).text(label ? `${label}: ${value}` : value));
        };

        console.log(track);
        addTag('', formatTrackLength(track.length, job.video_type), 'track-tag-duration');
        addTag('', track.fps ? `${track.fps} FPS` : null);
        addTag('', track.aspect_ratio);
        if (track.main_feature) addTag('', 'Main feature', 'track-tag-feature');

        info.append(heading, tags);

        // rip status
        const rip_status = $('<span>')
            .addClass(`track-tag track-tag-rip-status ${track.ripped ? 'is-ripped' : 'is-pending'}`)
            .append($('<i>').addClass(`fa-solid ${track.ripped ? 'fa-check' : 'fa-circle-dot'}`).attr('aria-hidden', 'true'))
            .append(document.createTextNode(track.ripped ? 'Ripped' : 'Not ripped'));
        info.find('.track-tags').append(rip_status);

        // track status
        const track_status = track.status || TrackState.TRACK_WAITING;
        const status_label = $('<span>')
            .addClass(`track-status track-tag-status-${track_status.replace(/[^a-z0-9-]/gi, '').toLowerCase()}`)
            .text(track_status);
        row.append(info, status_label);

        // skip
        if (!manual_edit && !track.process)
            row.addClass('skip-track');

        if (track.process)
            num_tracks_to_process++;

        if (manual_edit) {
            const checkbox = $('<input>', {
                type: 'checkbox',
                class: 'track-checkbox',
                checked: Boolean(track.process),
                'aria-label': `Process ${title}`
            }).on('change', function () {
                const input = this;
                const local_job_id = getJobIds(job).jobId;

                $.ajax({
                    url: '/jobdetail_track',
                    method: 'POST',
                    contentType: 'application/json',
                    headers: {
                        'X-CSRFToken': $('meta[name="csrf-token"]').attr('content')
                    },
                    data: JSON.stringify({
                        job_id: local_job_id,
                        track_id: track.track_id,
                        process: input.checked
                    })
                }).fail(() => {
                    input.checked = !input.checked;
                });
            });

            const label = $('<label>')
                .addClass('arm-checkbox track-select')
                .append(checkbox, $('<span>'));

            row.prepend(label);
        }

        container.append(row);
    });

    if (manual_time_remaining.expired && job.manual_edit)
        $('<div>', {
            class   : 'flash-alert flash-danger',
            html    : '<i class="fa-solid fa-triangle-exclamation"></i> Waiting for manual input expired!'
        }).appendTo(container);

    else if (manual_edit) {
        $('<button>', {
            type        : 'button',
            class       : 'arm-button arm-button-primary track-start',
            disabled    : num_tracks_to_process <= 0,
            html        : '<i class="fa-solid fa-play" aria-hidden="true"></i> Start ripping'
        }).on('click', function () {
            const local_job_id = getJobIds(job).jobId;

            if (num_tracks_to_process <= 0) {
                console.log('no tracks selected');
                return;
            }

            $.ajax({
                url         : '/jobdetail_ready',
                method      : 'POST',
                contentType : 'application/json',
                headers     : {
                    'X-CSRFToken': $('meta[name="csrf-token"]').attr('content')
                },
                data        : JSON.stringify({
                    job_id: local_job_id,
                })
            }).fail(() => {
                alert();
            });
        }).appendTo(actions);
    }
}

export function renderJobPipeline(job) {
    const status        = job.status;
    const finished      = JobStateGroup.FINISHED.has(status);
    const failed        = status === JobState.FAILURE;
    const successful    = status === JobState.SUCCESS;

    const skipTranscode = safe_bool(job.config?.SKIP_TRANSCODE);

    const currentIndex = finished
        ? JOB_PIPELINE_STAGES.length - 1
        : JOB_PIPELINE_STAGES.findIndex(stage => stage.status === status);

    const steps = JOB_PIPELINE_STAGES.map((stage, index) => {
        const step_disabled
            = skipTranscode && ['waiting_transcode', 'transcoding'].includes(stage.status);

        let state = 'pipeline-pending';
        let icon = stage.icon;

        if (step_disabled) {
            state   = 'step-disabled';
        } else if (finished && successful && index <= currentIndex) {
            state   = 'pipeline-done';
            icon    = 'fa-check';
        } else if (finished && failed && index === currentIndex) {
            state   = 'pipeline-failed';
            icon    = 'fa-xmark';
        } else if (!finished && currentIndex !== -1 && index < currentIndex) {
            state   = 'pipeline-done';
            icon    = 'fa-check';
        } else if (!finished && index === currentIndex) {
            state   = 'pipeline-current';
        }

        return `
            <div class="job-pipeline-step ${state}">
                <span class="job-pipeline-icon">
                    <i class="fa-solid ${icon}" aria-hidden="true"></i>
                </span>
                <span class="job-pipeline-label">${stage.label}</span>
            </div>`;
    }).join('');

    return `
        <div class="job-status-pipeline" data-status="${status}" aria-label="Job status pipeline">
            ${steps}
        </div>
    `;
}

export function renderProgress(job) {
    if (!jobHasProgress(job)) return '';

    return `
        <div class="job-progress" data-job-status="${job.status}">
            <div class="job-progress-header">
                <span id="job_stage">${job.stage}</span>
                <span id="job_percent">${job.progress}%</span>
            </div>
            <div class="progress-track">
                <div id="job_progress_bar" class="progress-value" style="width:${job.progress_round}%"></div>
            </div>
            <div class="job-progress-meta">
                <span id="_eta">ETA ${job.eta || 'Unknown'}</span>
                ${job.status === 'transcoding' ? `
                    <span id="job_cur_fps">${job.cur_fps || 0} FPS</span>
                    <span id="job_avg_fps">AVG ${job.avg_fps || 0} FPS</span>
                ` : ''}
            </div>
        </div>`;
}

export function renderJobMeta(job, ids) {
    return `
        <div class="job-meta">
            <div class="job-meta-item">
                <span class="job-meta-label">Ripping Mode</span>
                <span data-field="mode" class="job-mode-badge ${safe_bool(job.manual_mode) ? 'job-mode-manual' : 'job-mode-auto'}">
                    ${safe_bool(job.manual_mode) ? 'Manual' : 'Auto'}
                </span>
            </div>
            <div class="job-meta-item">
                <span class="job-meta-label">Type</span>
                <span data-field="video_type">${job.video_type}</span>
            </div>
            <div class="job-meta-item">
                <span class="job-meta-label">Year</span>
                <span data-field="year">${job.year}</span>
            </div>
            <div class="job-meta-item">
                <span class="job-meta-label">Device</span>
                <span data-field="devpath">${job.devpath}</span>
            </div>
            <div class="job-meta-item">
                <span class="job-meta-label">Ripper</span>
                <span data-field="ripper">${getRipperName(job, ids)}</span>
            </div>
            <div class="job-meta-item">
                <span class="job-meta-label">Method</span>
                <span data-field="ripmethod">${job.config.RIPMETHOD}</span>
            </div>
            <div class="job-meta-item">
                <span class="job-meta-label">Feature</span>
                <span data-field="mainfeature">${job.config.MAINFEATURE}</span>
            </div>
            <div class="job-meta-item">
                <span class="job-meta-label">Length</span>
                <span data-field="length">${job.config.MINLENGTH} – ${job.config.MAXLENGTH}</span>
            </div>
        </div>
    `;
}

export function renderJobActions(job, ids, authenticated) {
	if (!authenticated) return '';

	const hidden = !ids.local ? ' hidden' : '';

    let actions= '';

    // job has finished, failed or succesfull
    if (JobStateGroup.FINISHED.has(job.status)) {
        actions += `
            <button class="icon-button danger" type="button"
                data-modal="confirm"
                data-type="delete"
                data-jobid="${job.job_id}"
                data-href="json?job=${ids.jobId}&mode=delete"
                data-tooltip="Delete Job">
                <i class="fa-solid fa-trash"></i>
            </button>
        `;
    }

    // job is running
    else {
        actions += `
            <div class="job-actions${hidden}">
                <button class="icon-button danger" type="button"
                    data-modal="confirm"
                    data-type="abandon"
                    data-jobid="${job.job_id}"
                    data-href="json?job=${ids.jobId}&mode=abandon"
                    data-tooltip="Abandon Job">
                    <i class="fa-solid fa-ban"></i>
                </button>
        `;
    }

    // view log
    actions += `
			<a class="icon-button"
                target="_blank",
				href="logs?logfile=${job.logfile}&mode=tail"
				data-tooltip="View Log">
				<i class="fa-solid fa-terminal"></i>
			</a>
    `;

    // title actions
	if (!JobStateGroup.POSTPROCESSING.has(job.status)
        && !JobStateGroup.FINISHED.has(job.status) && job.video_type !== 'Music')
    {
		actions += `
			<a class="icon-button"
				href="titlesearch?job_id=${ids.jobId}"
				data-tooltip="Title Search">
				<i class="fa-solid fa-magnifying-glass"></i>
			</a>

			<a class="icon-button"
				href="customTitle?job_id=${ids.jobId}"
				data-tooltip="Custom Title">
				<i class="fa-regular fa-pen-to-square"></i>
			</a>`;
	}

    // settings and misc
	actions += `
			<details class="job-actions-menu">
				<summary class="icon-button"
					aria-label="More actions"
					title="More actions">
					<i class="fa-solid fa-ellipsis"></i>
				</summary>

				<div class="job-actions-menu-content">
					<a href="changeparams?config_id=${ids.jobId}">
						<i class="fa-solid fa-sliders"></i>
						<span>Edit Settings</span>
					</a>

					<button type="button"
						data-modal="confirm"
						data-type="fixperms"
						data-jobid="${job.job_id}"
						data-href="json?mode=fixperms&job=${ids.jobId}">
						<i class="fa-solid fa-wrench"></i>
						<span>Fix Permissions</span>
					</button>
				</div>
			</details>
		</div>`;

	return actions;
}

export function renderJob(job, authenticated, placeholder=false) {
    const ids       = getJobIds(job);
    const dateInfo  = formatTimestamp(job.start_time);

    return `
        <article class="job-card" ${placeholder ? 'data-placeholder' : ''} id="jobId${job.job_id}">
            <a href="#" class="job-poster-link" data-modal="jobs_details" data-jobid="${job.job_id}">
                ${posterCheck(job)}
            </a>

            <div class="job-content">
                <header class="job-header">
                    <div>
                        <h2 id="job_title" data-modal="jobs_details" data-jobid="${job.job_id}">${getJobTitle(job)}</h2>
                        <span class="job-id">${job.job_id}</span>
                    </div>

                    <div id="job_status_badge_wrapper">
                        ${renderJobStatusBadge(job)}
                    </div>
                </header>

                ${renderJobMeta(job, ids)}

                <div id="job_progress_section">${renderProgress(job)}</div>

                <div class="job-footer">
                    <div class="job-time">
                        <span title="${dateInfo.title}">
                            <i class="fa-regular fa-clock"></i> 
                            <span id="job_start_time">${dateInfo.relative}</span>
                        </span>
                        <span>
                            <i class="fa-solid fa-stopwatch"></i>
                            ${(job.job_length && job.job_length !== 'None') ? job.job_length : 'Ongoing'}
                        </span>
                    </div>
                    <div id="job_actions">
                        ${renderJobActions(job, ids, authenticated)}
                    </div>
                </div>
            </div>
        </article>`;
}

export function updateJobItem(job, authenticated) {
    const _card = $(`#jobId${job.job_id}`);
    if (!_card.length) return;

    const ids           = getJobIds(job);
    const dateInfo      = formatTimestamp(job.start_time);
    const jobTitle      = getJobTitle(job);

    const title         = _card.find('#job__title');
    const poster        = _card.find('.job-poster');
    const status        = _card.find('#job_status_badge_wrapper');
    const start_time    = _card.find('#job_start_time');
    const progress      = _card.find('#job_progress_section');
    const actions       = _card.find('#job_actions');

    if (title.length && title.text() !== jobTitle)
        title.text(jobTitle);

    if (start_time.length && start_time.text() !== dateInfo.relative)
        start_time.text(dateInfo.relative);

    if (poster.length && job.poster_url !== 'None' && job.poster_url !== 'N/A' && poster.attr('src') !== job.poster_url)
        poster.attr('src', job.poster_url);

    if (progress.length)
        progress.html(renderProgress(job));

    if (status.length)
        status.html(renderJobStatusBadge(job));

    if (actions.length)
        actions.html(renderJobActions(job, ids, authenticated));

    _card.find('[data-field="year"]').text(job.year);
    _card.find('[data-field="video_type"]').text(job.video_type);
    _card.find('[data-field="devpath"]').text(job.devpath);
    _card.find('[data-field="ripper"]').text(getRipperName(job, getJobIds(job)));
    _card.find('[data-field="ripmethod"]').text(job.config.RIPMETHOD);
    _card.find('[data-field="mainfeature"]').text(job.config.MAINFEATURE);
    _card.find('[data-field="length"]').text(`${job.config.MINLENGTH} - ${job.config.MAXLENGTH}`);
}

export function removeJobItem(job) {
    $('#jobId' + job.job_id).remove();
}

export function addJobItem(job, authenticated) {
    return renderJob(job, authenticated);
}

import { activeServers, JOB_LIST_CONTAINER, JobStateGroup } from '../common.js';
import { job_refresh } from './state.js';
import { updateJobItem, addJobItem, renderJob, removeJobItem } from './job.js';
import { ARM } from '../modal/modal.js';

let job_placeholder = null;

/**
 * Function to check for active jobs from the return from api
 * *** This doesn't work as it should when arm has child links
 * @param data returned data from ajax
 * @param serverIndex current server index count (added to the front of job id's)
 */
export function checkActiveJobs(data, serverIndex) {
	const results = Object.values(data.results || {});

	job_refresh.activeJobs.forEach(function (activeJob) {
		const matchingJob = results.find(function (job) {
			return String(activeJob.job_id) ===
				`${serverIndex}_${job.job_id}`;
		});

		activeJob.active = matchingJob
			? !JobStateGroup.FINISHED.has(matchingJob.status) // only mark unfinshed jobs active
			: false;
	});
}

/**
 * Function that is run when data is received back from json api
 * @param data all data returned from the ajax request
 * @param serverIndex
 * @param serverUrl the url of the server the job is running on
 * @param serverCount
 * @returns {*}
 */
export function refreshJobsSuccess(data, serverIndex, serverUrl, serverCount) {
    checkActiveJobs(data, serverIndex);

    $.each(data.results, function (_index, job) {
        job.job_id      = `${serverIndex}_${job.job_id}`;
        job.ripper      = (data.arm_name ? data.arm_name : '');
        job.server_url  = serverUrl;
        job.active      = !JobStateGroup.FINISHED.has(job.status);

        const job_index = job_refresh.activeJobs.findIndex(e => e.job_id === job.job_id);

        // exists
        if (job_index !== -1) {
            job_refresh.activeJobs[job_index] = job;
            updateJobItem(job, data.authenticated);
        }

        // add to list
        else {
            job_refresh.activeJobs.push(job);

            // only add unfinished jobs
            if (!JobStateGroup.FINISHED.has(job.status)) {
                $(JOB_LIST_CONTAINER).append(
                    addJobItem(job, data.authenticated)
                );
            }
        }

        serverCount--;
    });

    return serverCount;
}

export function removeInactiveJobs(update_only = false) {
	$.each(job_refresh.activeJobs, function (index, job) {
		if (job && !job.active) {
            if (!update_only)
                setTimeout(() => removeJobItem(job), 200);

			job_refresh.activeJobs.splice(index, 1);
		}
	});
}

export function sortJobs(update_only = false) {
    if (update_only)
        return;

	$(`${JOB_LIST_CONTAINER} .job-card`).sort(function (a, b) {
		return a.id.localeCompare(b.id);
	}).appendTo(JOB_LIST_CONTAINER);
}

export function createPlaceholderJob() {
    return {
        job_id      : 'placeholder',
        status      : 'waiting',
        active      : true,
        manual_mode : 'False',
        start_time  : Date.now(),
        job_length  : 'Ongoing',
        title       : 'Waiting for job...',
        year        : '',
        video_type  : '',
        devpath     : '',
        imdb_id     : '',
        config: {
            RIPMETHOD   : '',
            MAINFEATURE : '',
            MINLENGTH   : '',
            MAXLENGTH   : ''
        },
        tracks: []
    };
}

export function addJobPlaceholder(update_only) {
    if (update_only)
        return;

    const numActiveJobs = job_refresh.activeJobs.filter(job => job?.active).length;

    if (numActiveJobs <= 0) {
        if (!job_placeholder || !job_placeholder.length) {
            const placeholderAuthenticated = false;

            $('#joblist').append(
                renderJob(createPlaceholderJob(), placeholderAuthenticated, true)
            );

            job_placeholder = $('#joblist .job-card[data-placeholder]');
        }
    } else if (job_placeholder && job_placeholder.length) {
        job_placeholder.remove();
        job_placeholder = null;
    }
}

/**
 * Function set as an interval to update all jobs from api
 */
export function refreshJobs(update_only = false) {
    let i = activeServers.length;

    $.each(activeServers, function (serverIndex, serverUrl) {
        $.getJSON(serverUrl + '/json?mode=joblist')
            .done(function (data) {
                i = refreshJobsSuccess(data, serverIndex, serverUrl, i);
            })
            .fail(function () {
                --i;
            })
            .always(function () {
                // Update job pipeline modal.
                $(document).trigger(
                    `arm:modal-update_${ARM.modal.jobs.pipeline.modal}`,
                    {}
                );

                // Update job details modal.
                $(document).trigger(
                    `arm:modal-update_${ARM.modal.jobs.details.modal}`,
                    {}
                );

                // Sort jobs after updates are processed
                sortJobs(update_only);
                removeInactiveJobs(update_only);
                addJobPlaceholder(update_only);
            });
    });
}

export function startLogViewer(mode, logfile, interval = 3000, element_id = '#log_file_content') {
    const log_element = $(element_id);

    if (!__is_authenticated_simple()) {
        log_element.remove();
        return;
    }

    if (!logfile) {
        console.error(`Invalid log file: ${logfile}`);
        return;
    }

    if (!log_element.length){
        console.error('Invalid log dom element');
        return;
    }

    const element = log_element[0];
    const threshold = 5;

    let lastText        = '';
    let initialized     = false;
    let loading         = false;
    let followBottom    = true;

    function updateFollowBottom() {
        followBottom =
            element.scrollHeight - element.scrollTop - element.clientHeight <= threshold;
    }

    element.addEventListener('scroll', updateFollowBottom);

    function scrollToBottom() {
        if (followBottom)
            element.scrollTop = element.scrollHeight;
    }

    function fetchLog() {
        if (loading)
            return;

        loading = true;

        $.get('/logreader', {
            logfile : logfile,
            mode    : mode
        })
        .done(function (data) {
            const text = data.content;
            let update = false;

            if (!initialized) {
                log_element.text(text);
                lastText    = text;
                initialized = true;
                update      = text.length > 0;
            }
            else if (text.startsWith(lastText) && text.length > lastText.length) {
                log_element.append(document.createTextNode(
                    text.substring(lastText.length)
                ));
                lastText    = text;
                update      = true;
            }
            else if (text !== lastText) {
                log_element.text(text);
                lastText    = text;
                update      = true;
            }

            if (update)
                scrollToBottom();
        })
        .fail(function (xhr, status, error) {
            console.error('Failed to refresh logfile:', status, error);
        })
        .always(function () {
            loading = false;
        });
    }

    fetchLog();

    const timer = window.setInterval(fetchLog, interval);

    // Return a cleanup function to stop polling and remove the listener.
    return function cleanup() {
        log_element.text('');
        window.clearInterval(timer);
        element.removeEventListener('scroll', updateFollowBottom);
    };
}

