export const ARM = {
    storage: {
        get(key) {
            return localStorage.getItem(key) === 'true';
        },

        set(key, value) {
            localStorage.setItem(key, String(value));
        }
    },

	modal: {
		active: null,
		lastFocus: null,

        // modals
        confirm: {},
        database: {},
		jobs: {},

        // global handlers
        show(selector) {
            const modal = $(selector);

            if (!modal.length) {
                console.warn(`Modal not found: ${selector}`);
                return;
            }

            if (this.active && this.active !== selector) {
                this.hide(this.active, false);
            } else if (!this.active) {
                this.lastFocus = document.activeElement;
            }

            this.active = selector;

            modal
                .addClass('open')
                .attr('aria-hidden', 'false');

            $('body').addClass('modal-open');

            modal.find('.arm-modal-dialog').trigger('focus');
        },

		hide(selector = this.active, restoreFocus = true) {
			if (!selector) {
				return;
			}

			$(selector)
				.removeClass('open')
				.attr('aria-hidden', 'true');

			if (this.active !== selector) {
				return;
			}

			$(document).trigger(`arm:modal-close_${this.active}`, {});

			this.active = null;
			$('body').removeClass('modal-open');

			// ??
			if (restoreFocus && this.lastFocus) {
				$(this.lastFocus).trigger('focus');
			}

			this.lastFocus = null;


		}
	}
};

$(function() {
	$(document).on('click', '[data-modal-close]', function() {
		const modal = $(this).closest('.arm-modal');

		if (modal.length) {
			ARM.modal.hide(`#${modal.attr('id')}`);
		}
	});

	$(document).on('keydown', function(e) {
		if (e.key === 'Escape' && ARM.modal.active) {
			ARM.modal.hide();
		}
	});
});

import { activeServers } from './common.js';
import { formatTimestamp } from './time.js';

export function addNotification(title, body, notificationId, timestamp = null) {
	const timeout = Number.parseInt(getNotifyTimeout(), 10);
    const fallback_delay = 15000;
	const delay = Number.isFinite(timeout) ? Math.max(0, timeout) : fallback_delay;

    const notification = $(`
        <div class="notification" role="status">
            <div class="notification-header">
                <span class="notification-icon">
                    <i class="fa-solid fa-check" aria-hidden="true"></i>
                </span>
                <strong class="notification-title"></strong>
                <small class="notification-time">-</small>
            </div>
            <button type="button" class="notification-close"
                aria-label="Dismiss notification">&times;</button>
            <div class="notification-body"></div>
        </div>
    `);

    notification.attr('id', `notification${notificationId}`);
    notification.find('.notification-title').text(title);
    notification.find('.notification-body').text(body);

    if (!timestamp) {
        notification.find('.notification-time').text(
            'just now'
        );
    }
    else{
        const dateInfo = formatTimestamp(timestamp);
        notification.find('.notification-time').text(dateInfo.relative);
    }

    $('#notification_container').append(notification);

	let dismissed = false;
	let timer;

	function dismiss() {
		if (dismissed) return;
		dismissed = true;
		clearTimeout(timer);

		notification.addClass('notification-hiding');
		notification.one('transitionend', function() {
			notification.remove();
		});

		// Fallback for reduced motion or missing transition events.
		setTimeout(() => notification.remove(), 250);

		pingReadNotify(notificationId);
	}

	notification.find('.notification-close').on('click', dismiss);

	if (delay > 0) {
		timer = setTimeout(dismiss, delay);
	}
}

export function pingReadNotify(id) {
    // this does not check child server ..
    $.ajax({
        url: `/json?mode=read_notification&notify_id=${id}`,
        type: 'get',
        timeout: 2000,
        success: function (data) {
            console.log(data)
        }
    });
}

// Get the notifaction timeout settings from UI Settings via JSON
export function getNotifyTimeout() {
    // this does not check child server ..
    let notify = 6500;

    $.ajax({
        url: '/json?mode=notify_timeout',
        type: 'get',
        timeout: 2000,
        success: function (data) {
            notify = data.notify_timeout;
        }
    });

    return notify;
}

export function parseNotifications(data) {
    $.each(data.notes, function (notifyIndex, note) {
        if ($(`#notification${note.id}`).length)    // exists
            return null

        addNotification(note.title, note.message, note.id, note.trigger_time);
    });
}

export function getNotifications() {
    $.each(activeServers, function (serverIndex, serverUrl) {
        $.getJSON(`${serverUrl}/get_notications`)
            .done(function (data) {
                parseNotifications(data);
            });
    });
}

$(function () {
    function sendSettings(formToSend, sendTo) {
        const data = formToSend.serializeArray();

        formToSend.find('input[type="checkbox"]').each(function () {
            data.push({
                name: this.name,
                value: this.checked ? 'True' : 'False'
            });
        });

        $.ajax({
            type: 'POST',
            url: sendTo,
            data: $.param(data)
        }).done(function (data) {
            if (data.success === true) {
                console.log(data);
            }
        });
    }

    $('#uiSettings').submit(function (e) {
